 sealed class WindowsRegistryStore:ISceneBlockRegistryStore {
  public string GetCommand(){using(var k=Registry.CurrentUser.OpenSubKey(Key+"\\shell\\open\\command"))return k==null?null:k.GetValue("") as string;}
  public void SetCommand(string command){using(var k=Registry.CurrentUser.CreateSubKey(Key)){if(k.GetValue("")==null||Convert.ToString(k.GetValue(""))=="URL:SceneBlock AI")k.SetValue("","URL:SceneBlock AI");if(k.GetValue("URL Protocol")==null)k.SetValue("URL Protocol","");}using(var k=Registry.CurrentUser.CreateSubKey(Key+"\\shell\\open\\command"))k.SetValue("",command);}
  public bool DeleteOwnedCommand(string expected){if(GetCommand()!=expected)return false;using(var k=Registry.CurrentUser.OpenSubKey(Key+"\\shell\\open\\command",true)){if(k!=null)k.DeleteValue("",false);}Prune(Key+"\\shell\\open\\command");Prune(Key+"\\shell\\open");Prune(Key+"\\shell");using(var k=Registry.CurrentUser.OpenSubKey(Key,true)){if(k!=null){if(Convert.ToString(k.GetValue(""))=="URL:SceneBlock AI")k.DeleteValue("",false);if(k.GetValue("URL Protocol") is string&&Convert.ToString(k.GetValue("URL Protocol"))=="")k.DeleteValue("URL Protocol",false);}}Prune(Key);return true;}
  static void Prune(string path){using(var k=Registry.CurrentUser.OpenSubKey(path)){if(k==null||k.ValueCount!=0||k.SubKeyCount!=0)return;}Registry.CurrentUser.DeleteSubKey(path,false);}
 }
 sealed class MemoryRegistry:ISceneBlockRegistryStore {public string Value;public string GetCommand(){return Value;}public void SetCommand(string value){Value=value;}public bool DeleteOwnedCommand(string expected){if(Value!=expected)return false;Value=null;return true;}}
 [STAThread] static void Main(string[] args){if(args.Length==2&&args[0]=="--test-confirmations"){Fresh(args[1]);TestConfirmationDismissal(args[1]);return;}if(args.Length==2&&args[0]=="--preview-confirmation"){Application.EnableVisualStyles();using(var f=CreateConfirmation("프로그램 제거 확인","삭제할 파일 (예시):\r\nC:\\SceneBlock-fixture\\AI\\2.8.0\\node.exe\r\n\r\n보존 항목 / 이유:\r\n사용자 설정 및 변경된 파일은 보존합니다.",true))SceneBlockTheme.Render(f,args[1]);return;}if(args.Length==1&&args[0]=="--verify-payload"){Verify();return;}if(args.Length==2&&args[0]=="--test-upgrade"){TestUpgrade(args[1]);return;}if(args.Length==2&&args[0]=="--test-lifecycle"){TestLifecycle(args[1]);return;}if(args.Length>0&&args[0]!="--preview"&&args[0]!="--uninstall")throw new Exception("Unknown option");Application.EnableVisualStyles();if(args.Length==2&&args[0]=="--preview"){using(var f=new SceneBlockSetup())SceneBlockTheme.Render(f,args[1]);return;}if(args.Length>1||(args.Length==1&&args[0]!="--uninstall"))throw new Exception("Invalid arguments");using(var form=new SceneBlockSetup()){if(args.Length==1&&args[0]=="--uninstall")form.Shown+=(s,e)=>form.Run(()=>form.Remove(false));Application.Run(form);}}
 static string Hash(Stream input){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(input)).Replace("-","").ToLowerInvariant();}
 static string HashFile(string file){using(var s=File.OpenRead(file))return Hash(s);}
 static void Safe(string path){for(string p=Path.GetFullPath(path);p!=null;p=Path.GetDirectoryName(p))if((File.Exists(p)||Directory.Exists(p))&&(File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new Exception("연결된 폴더/파일은 사용할 수 없습니다: "+p);}
 static Dictionary<string,string> PayloadHashes(){var result=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("payload.zip"))using(var z=new ZipArchive(stream,ZipArchiveMode.Read)){foreach(var e in z.Entries){if(e.FullName.Contains("..")||Path.GetFileName(e.FullName)!=e.FullName||e.FullName.IndexOfAny(new[]{'/', '\\', ':'})>=0)throw new Exception("Invalid payload path");using(var input=e.Open())result.Add(e.FullName,Hash(input));}}return result;}
 static void Verify(){var hashes=PayloadHashes();if(hashes.Count<9||!hashes.ContainsKey("node.exe")||!hashes.ContainsKey("2026-10-25-SceneBlock-Approval.exe"))throw new Exception("Incomplete payload");}
 static Dictionary<string,Dictionary<string,string>> Legacy(){var result=new Dictionary<string,Dictionary<string,string>>();using(var s=Assembly.GetExecutingAssembly().GetManifestResourceStream("legacy-hashes.txt")){if(s==null)return result;using(var r=new StreamReader(s)){string line;while((line=r.ReadLine())!=null){if(line.Length==0)continue;var p=line.Split('\t');if(p.Length!=3)throw new Exception("Invalid legacy hashes");if(!result.ContainsKey(p[0]))result.Add(p[0],new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase));result[p[0]].Add(p[1],p[2]);}}}return result;}
 static bool Busy(string version){string folder=Path.GetFullPath(Path.Combine(Root,version))+Path.DirectorySeparatorChar;foreach(var p in Process.GetProcesses()){using(p){if(p.Id==Process.GetCurrentProcess().Id)continue;try{string file=p.MainModule.FileName;if(Path.GetFullPath(file).StartsWith(folder,StringComparison.OrdinalIgnoreCase))return true;}catch{try{if(p.ProcessName=="node"||p.ProcessName.StartsWith("2026-10-",StringComparison.OrdinalIgnoreCase))return true;}catch{return true;}}}}return false;}
 SceneBlockSetup(){SceneBlockTheme.Apply(this,"SceneBlock AI 설치 관리 v"+Version,new Size(760,580));SceneBlockTheme.Brand(this);SceneBlockTheme.Text(this,"설치 및 연결 관리",28,66,704,38,20,SceneBlockTheme.Foreground);SceneBlockTheme.Text(this,"현재 사용자 설치 · 버전별 파일 보존 · 삭제 전 정확한 목록 확인",28,111,704,32,10,SceneBlockTheme.Muted);status.SetBounds(28,153,704,245);status.ForeColor=SceneBlockTheme.Foreground;Controls.Add(status);
 var install=SceneBlockTheme.Button(this,"설치 · 업데이트",28,414,340,true);install.Click+=(s,e)=>Run(Install);
 var repair=SceneBlockTheme.Button(this,"연결 복구",386,414,346,false);repair.Click+=(s,e)=>Run(Repair);
 var uninstall=SceneBlockTheme.Button(this,"프로그램 제거",28,466,340,false);uninstall.Click+=(s,e)=>Run(()=>Remove(false));
 var cleanup=SceneBlockTheme.Button(this,"구버전 정리",386,466,346,false);cleanup.Click+=(s,e)=>Run(()=>Remove(true));
 var close=SceneBlockTheme.Button(this,"닫기",592,526,140,false);close.Click+=(s,e)=>Close();CancelButton=close;
 try{manager=new SceneBlockInstallationManager(Root,Version,Busy,new WindowsRegistryStore(),Legacy());RefreshStatus();}catch(Exception e){status.Text=e.Message;install.Enabled=repair.Enabled=uninstall.Enabled=cleanup.Enabled=false;}}
 void Run(Action action){try{action();RefreshStatus();}catch(Exception e){ShowText("작업 중단",e.Message,false);try{RefreshStatus();}catch{}}}
 void RefreshStatus(){var lines=new List<string>{"설치 위치: "+Root,"제공 버전: "+Version};var versions=manager.Scan();if(versions.Count==0)lines.Add("설치된 버전이 없습니다.");foreach(var v in versions)lines.Add("v"+v.Version+" · "+(v.Registered?"현재 웹 연결 · ":"")+(v.Busy?"사용 중 · ":"")+(v.Complete?"정상":v.Recognized?"파일 확인 필요":"소유권 미확인 / 보존"));status.Text=String.Join(Environment.NewLine,lines);}
 static Form CreateConfirmation(string title,string text,bool confirm){var f=new Form();SceneBlockTheme.Apply(f,title,new Size(760,560));SceneBlockTheme.Brand(f);var box=new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,WordWrap=false,BackColor=SceneBlockTheme.Panel,ForeColor=SceneBlockTheme.Foreground,BorderStyle=BorderStyle.FixedSingle,Location=new Point(28,70),Size=new Size(704,408),Text=text};f.Controls.Add(box);var cancel=SceneBlockTheme.Button(f,confirm?"취소":"닫기",410,498,150,false);cancel.Name="CancelAction";cancel.DialogResult=DialogResult.Cancel;f.CancelButton=cancel;if(confirm){var yes=SceneBlockTheme.Button(f,"목록 확인 후 실행",574,498,158,true);yes.DialogResult=DialogResult.OK;}f.ActiveControl=cancel;return f;}
 bool ShowText(string title,string text,bool confirm){using(var f=CreateConfirmation(title,text,confirm))return f.ShowDialog(this)==DialogResult.OK;}
 static void TestConfirmationDismissal(string root){Application.EnableVisualStyles();string marker=Path.Combine(root,"2026-10-25-cancel-preservation.txt");File.WriteAllText(marker,"unchanged");for(int mode=0;mode<3;mode++){int choice=mode;using(var f=CreateConfirmation("제거 확인 테스트","삭제할 파일:\r\n"+marker,true)){f.ShowInTaskbar=false;using(var timer=new Timer()){timer.Interval=80;timer.Tick+=(s,e)=>{timer.Stop();if(choice==0)((Button)f.Controls["CancelAction"]).PerformClick();else if(choice==1){typeof(Form).GetMethod("ProcessDialogKey",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(f,new object[]{Keys.Escape});}else f.Close();};timer.Start();Check(f.ShowDialog()!=DialogResult.OK,"Dismissal approved removal");}}Check(File.ReadAllText(marker)=="unchanged","Dismissal mutated files");}File.WriteAllText(Path.Combine(root,"2026-10-25-confirmations-test.txt"),"PASS: actual confirmation Cancel button, Esc, window Close return non-OK; fixture unchanged; no registry or installed folder accessed");}
 static void ExtractPayload(string folder){Verify();Safe(folder);var hashes=PayloadHashes();foreach(var pair in hashes){string file=Path.Combine(folder,pair.Key);Safe(file);if(File.Exists(file)&&HashFile(file)!=pair.Value)throw new Exception("다른 내용의 기존 파일을 보존했습니다: "+file);}Directory.CreateDirectory(folder);using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("payload.zip"))using(var z=new ZipArchive(stream,ZipArchiveMode.Read)){foreach(var e in z.Entries){string file=Path.Combine(folder,e.FullName);Safe(file);if(!File.Exists(file))using(var input=e.Open())using(var output=new FileStream(file,FileMode.CreateNew))input.CopyTo(output);}}}
 static void Preflight(SceneBlockInstallationManager m,ISceneBlockRegistryStore registry){Safe(Root);var versions=m.Scan();if(versions.Any(v=>v.Busy))throw new Exception("연결 프로그램이 사용 중입니다. 웹에서 연결을 해제하고 종료 후 다시 시도하세요.");if(versions.Any(v=>new System.Version(v.Version)>new System.Version(Version)))throw new Exception("더 최신 버전이 설치되어 있어 이전 버전 설치를 중단했습니다.");var command=registry.GetCommand();if(!String.IsNullOrEmpty(command)&&!versions.Any(v=>v.Recognized&&command==m.BuildCommand(v.Version)))throw new Exception("다른 프로그램 또는 소유권 미확인 웹 연결을 보존했습니다.");}
 static void InstallAt(SceneBlockInstallationManager m,ISceneBlockRegistryStore registry,string folder){var versions=m.Scan();if(versions.Any(v=>v.Busy)||versions.Any(v=>new System.Version(v.Version)>new System.Version(Version)))throw new Exception("Busy or newer installation");string command=registry.GetCommand();if(!String.IsNullOrEmpty(command)&&!versions.Any(v=>v.Recognized&&command==m.BuildCommand(v.Version)))throw new Exception("Foreign registration preserved");Safe(folder);string source=Assembly.GetExecutingAssembly().Location,dest=Path.Combine(folder,ManagerName);Safe(dest);if(File.Exists(dest)&&HashFile(dest)!=HashFile(source))throw new Exception("기존 관리 파일을 보존했습니다: "+dest);var hashes=PayloadHashes();hashes.Add(ManagerName,HashFile(source));ExtractPayload(folder);if(!File.Exists(dest))File.Copy(source,dest,false);m.RecordManifest(Version,hashes);m.Repair(Version);}
 void Install(){var registry=new WindowsRegistryStore();Preflight(manager,registry);var hashes=PayloadHashes();var list=new List<string>{"설치 / 업데이트 v"+Version,"웹 연결 등록: "+manager.BuildCommand(Version),"이전 버전, 사용자 파일, 로그인 정보는 유지합니다.","","생성하거나 동일함을 확인할 파일:"};list.AddRange(hashes.Keys.Select(n=>Path.Combine(target,n)));list.Add(Path.Combine(target,ManagerName));list.Add(Path.Combine(target,SceneBlockInstallationManager.ManifestName));if(!ShowText("설치 · 업데이트 확인",String.Join(Environment.NewLine,list),true))return;Preflight(manager,registry);InstallAt(manager,registry,target);ShowText("설치 완료","v"+Version+" 설치 및 웹 연결 등록을 완료했습니다.\r\n관리 프로그램: "+Path.Combine(target,ManagerName),false);}
 void Repair(){var versions=manager.Scan().Where(v=>v.Complete).OrderByDescending(v=>new System.Version(v.Version)).ToList();if(versions.Count==0)throw new Exception("복구할 정상 설치가 없습니다. 설치 · 업데이트를 실행하세요.");var selected=versions[0];if(!ShowText("웹 연결 복구 확인","파일 삭제/교체 없이 다음 웹 연결을 등록합니다.\r\n"+manager.BuildCommand(selected.Version),true))return;manager.Repair(selected.Version);ShowText("복구 완료","v"+selected.Version+" 웹 연결을 복구했습니다.",false);}
 bool RelaunchForRemoval(){string exe=Path.GetFullPath(Assembly.GetExecutingAssembly().Location);if(!exe.StartsWith(Path.GetFullPath(Root)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))return false;string temp=Path.Combine(Path.GetTempPath(),"2026-10-25-SceneBlock-Manager-"+Guid.NewGuid().ToString("N"));Safe(temp);Directory.CreateDirectory(temp);string copy=Path.Combine(temp,ManagerName);File.Copy(exe,copy,false);Process.Start(new ProcessStartInfo(copy,"--uninstall"){UseShellExecute=true});Close();return true;}
 void Remove(bool oldOnly){if(!oldOnly&&RelaunchForRemoval())return;var plan=manager.PlanRemoval(oldOnly);var lines=new List<string>{oldOnly?"이전 버전 정리: 현재 제공 버전과 웹 연결 버전을 유지합니다.":"설치 제거: 확인된 원본 파일만 삭제합니다.","","삭제할 파일 (정확한 경로):"};lines.AddRange(plan.Files.Select(f=>f.Path));lines.Add("\r\n비어 있을 때만 삭제할 폴더:");lines.AddRange(plan.Directories);lines.Add("\r\n웹 연결 삭제: "+(plan.WillRemoveRegistration?plan.RegistrySnapshot:"없음"));lines.Add("\r\n보존 항목 / 이유:");lines.AddRange(plan.PreservedReasons);lines.Add("\r\n실행 차단 이유:");lines.AddRange(plan.BlockedReasons);if(!plan.CanExecute){ShowText("삭제할 수 없습니다",String.Join(Environment.NewLine,lines),false);return;}if(!ShowText(oldOnly?"이전 버전 정리 확인":"제거 확인",String.Join(Environment.NewLine,lines),true))return;var result=manager.Remove(plan);ShowText(result.Success?"작업 완료":"보존 항목 / 오류 확인","삭제 파일: "+result.RemovedFiles.Count+"\r\n"+String.Join("\r\n",result.PreservedReasons.Concat(result.Errors)),false);}
 static void TestUpgrade(string root){Fresh(root);var old=Path.Combine(root,"2.6.0");Directory.CreateDirectory(old);var marker=Path.Combine(old,"settings-preservation.txt");File.WriteAllText(marker,"keep");var next=Path.Combine(root,Version);ExtractPayload(next);ExtractPayload(next);if(File.ReadAllText(marker)!="keep")throw new Exception("Old version changed");string file=Path.Combine(next,"2026-10-23-on-demand.mjs");File.AppendAllText(file,"\n// modified");bool refused=false;try{ExtractPayload(next);}catch{refused=true;}if(!refused||!File.ReadAllText(file).EndsWith("// modified"))throw new Exception("Existing-file guard failed");File.WriteAllText(Path.Combine(root,"2026-10-25-upgrade-test.txt"),"PASS: payload extraction; old version preserved; identical reinstall; modified file refused; no real registry changes");}
 static void Fresh(string root){root=Path.GetFullPath(root);string workspace=Path.GetFullPath(Environment.CurrentDirectory).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;if(!root.StartsWith(workspace,StringComparison.OrdinalIgnoreCase)||Directory.Exists(root)||File.Exists(root))throw new Exception("Test root must be a fresh directory under current workspace");Safe(root);Directory.CreateDirectory(root);}
 static void Check(bool condition,string message){if(!condition)throw new Exception(message);}
 static void TestLifecycle(string root){Fresh(root);TestConfirmationDismissal(root);var registry=new MemoryRegistry();bool busy=false;var m=new SceneBlockInstallationManager(root,Version,delegate(string v){return busy;},registry,Legacy());string old=Path.Combine(root,"2.6.0");Directory.CreateDirectory(old);string marker=Path.Combine(old,"settings-preservation.txt");File.WriteAllText(marker,"preserve old settings");InstallAt(m,registry,Path.Combine(root,Version));Check(File.ReadAllText(marker)=="preserve old settings","Old version changed");Check(m.Scan().Any(v=>v.Version==Version&&v.Complete&&v.Registered),"Install failed");registry.Value=null;m.Repair(Version);Check(registry.Value==m.BuildCommand(Version),"Repair failed");var cancelled=m.PlanRemoval(false);Check(cancelled.Files.Count>0&&File.Exists(Path.Combine(root,Version,"node.exe")),"Cancelled plan mutated files");string unknown=Path.Combine(root,Version,"2026-10-25-user-file.txt");File.WriteAllText(unknown,"keep unknown");string registeredOld=Path.Combine(root,"2.8.0");ExtractPayload(registeredOld);m.RecordManifest("2.8.0",PayloadHashes());registry.Value=m.BuildCommand("2.8.0");string removableOld=Path.Combine(root,"2.7.0");ExtractPayload(removableOld);m.RecordManifest("2.7.0",PayloadHashes());var cleanup=m.PlanRemoval(true);Check(!cleanup.Files.Any(f=>f.Path.StartsWith(Path.Combine(root,Version)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)||f.Path.StartsWith(registeredOld+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)),"Cleanup selected current or registered version");Check(cleanup.Files.Any(f=>f.Path.StartsWith(removableOld+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)),"Cleanup omitted old owned version");var cleaned=m.Remove(cleanup);Check(cleaned.Errors.Count==0&&!Directory.Exists(removableOld)&&Directory.Exists(registeredOld)&&File.Exists(Path.Combine(root,Version,"node.exe")),"Cleanup failed");registry.Value=m.BuildCommand(Version);busy=true;Check(!m.PlanRemoval(false).CanExecute,"Busy removal permitted");busy=false;registry.Value="foreign command";bool refused=false;try{m.Repair(Version);}catch{refused=true;}Check(refused&&registry.Value=="foreign command","Foreign registry changed");registry.Value=m.BuildCommand(Version);var result=m.Remove(m.PlanRemoval(false));Check(result.Errors.Count==0&&File.ReadAllText(unknown)=="keep unknown"&&File.ReadAllText(marker)=="preserve old settings"&&registry.Value==null,"Uninstall preservation failed");File.WriteAllText(Path.Combine(root,"2026-10-25-lifecycle-test.txt"),"PASS: install; old settings preserved; repair; cancel plan has no mutation; current/registered cleanup retained; busy blocked; foreign registry preserved; uninstall unknown preserved; in-memory registry only");}
